  background: tokens.colors.panel,
  color: tokens.colors.text,
  padding: tokens.spacing.panelPadding,
  gap: tokens.spacing.controlGap,
  display: "grid",
};

function transform(text: string, mode: CaseMode, shouldTrim: boolean): string {
  const prepared: string = shouldTrim ? text.trim() : text;
  if (mode === "upper") return prepared.toUpperCase();
  if (mode === "lower") return prepared.toLowerCase();
  return prepared;
}

export function Component({ initialText }: Props): ReactElement {
  const [text, setText] = useState<string>(initialText);
  const [mode, setMode] = useState<CaseMode>("keep");
  const [shouldTrim, setShouldTrim] = useState<boolean>(false);
  const result: string = transform(text, mode, shouldTrim);
  const characters: string = String(result.length);

  function changeCase(event: ChangeEvent<HTMLSelectElement>): void {
    const value: string = event.currentTarget.value;
    if (value === "keep" || value === "upper" || value === "lower") {
      setMode(value);
    }
  }

  return (
    <div data-testid="panel" style={panelStyle}>
      <label>
        Text
        <textarea
          value={text}
          onChange={(event) => setText(event.currentTarget.value)}
        />
      </label>
