import { useState } from 'react';
import type { ChangeEvent, CSSProperties, ReactElement } from 'react';

export type Props = { initialText: string };
type CaseMode = 'keep' | 'upper' | 'lower';
type Theme = {
  colors: { panel: string; text: string };
  spacing: { padding: number; gap: number };
};

const theme: Theme = {
  colors: { panel: '#eef4ff', text: '#17345c' },
  spacing: { padding: 12, gap: 6 },
};

const panelStyle: CSSProperties = {
  display: 'grid',
  background: theme.colors.panel,
  color: theme.colors.text,
  padding: theme.spacing.padding,
  gap: theme.spacing.gap,
};

function normalize(text: string, trim: boolean, mode: CaseMode): string {
  const prepared: string = trim ? text.trim() : text;
  if (mode === 'upper') return prepared.toUpperCase();
  if (mode === 'lower') return prepared.toLowerCase();
  return prepared;
}

export function Component({ initialText }: Props): ReactElement {
  const [text, setText] = useState<string>(initialText);
  const [mode, setMode] = useState<CaseMode>('keep');
  const [trim, setTrim] = useState<boolean>(false);
  const result: string = normalize(text, trim, mode);

  return (
    <div data-testid="panel" style={panelStyle}>
      <label>
        Text
        <textarea
          value={text}
          onChange={(event: ChangeEvent<HTMLTextAreaElement>): void => {
            setText(event.target.value);
          }}
        />
      </label>
      <label>
        Case
        <select
          value={mode}
          onChange={(event: ChangeEvent<HTMLSelectElement>): void => {
            const value: string = event.target.value;
            if (value === 'keep' || value === 'upper' || value === 'lower') {
              setMode(value);
            }
          }}
        >
          <option value="keep">keep</option>
          <option value="upper">upper</option>
          <option value="lower">lower</option>
        </select>
      </label>
      <label>
        <input
          type="checkbox"
          checked={trim}
          onChange={(event: ChangeEvent<HTMLInputElement>): void => {
            setTrim(event.target.checked);
          }}
        />
        Trim
      </label>
      <output aria-label="Result" style={{ whiteSpace: 'pre-wrap' }}>
        {result}
      </output>
      <output aria-label="Characters">{String(result.length)}</output>
    </div>
  );
}
